// Unit tests for services/depGraph.js — traversal over STORED DAG documents.
// The documents are real builder output (proxy/notebook/dag.py) generated by
// tests/fixtures/gen_dag_fixtures.py into tests/fixtures/dag_*.json.
// Run with: node --test web/src/services/__tests__/depGraph.test.mjs
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import {
  changedVarsSince, changedVarsSinceBaseline, collectDownstream, collectUpstream, effectiveStatus, findCycleCells,
  graphFromDag, maxClock, newerDag, orderByPosition, relatedCells, runBaseline, staleNodes, withDagProvenance,
} from '../depGraph.js'
import { buildLineage } from '../lineage.js'
import { deriveSqlOutputVariable } from '../sqlOutputVariable.js'

const FIXTURES = join(dirname(fileURLToPath(import.meta.url)), '..', '..', '..', '..', 'tests', 'fixtures')
const load = (name) => JSON.parse(readFileSync(join(FIXTURES, name), 'utf8'))
const scenarios = (name) => load(name).scenarios

// Live cells as the browser holds them after a run (code == lastExecutedCode).
function liveCells(scenario, overrides = {}) {
  return scenario.cells.map(c => {
    const code = (scenario.live_code && scenario.live_code[c.id]) || c.code
    return {
      ...c, code, executionNumber: 1, lastExecutedCode: code, executedAt: '2024-01-01T00:00:00Z', output: 'ok',
      ...(overrides[c.id] || {}),
    }
  })
}

const sorted = (s) => [...s].sort()
const READERS = ['r31', 'r32', 'r42']
const CHAIN = scenarios('dag_mutation_chain.json')

for (const label of ['with_provenance', 'no_provenance']) {
  const sc = CHAIN[label]

  test(`mutation chain resolves builder → mutator → readers (${label})`, () => {
    const g = graphFromDag(sc.doc)
    assert.equal(g.inputsOf.get('mutator').get('products360'), 'builder', 'mutator depends on the builder')
    for (const r of READERS) assert.equal(g.inputsOf.get(r).get('products360'), 'mutator', `${r} reads the mutated frame`)
    assert.deepEqual(g.nodeById.get('mutator').mutates, ['products360'])
    assert.ok(!g.edges.some(e => e.from === e.to), 'no self-loops')
    assert.equal(findCycleCells(g.downstream).size, 0, 'no cycles')
    assert.equal(graphFromDag(sc.doc), g, 'cached per document object')
  })

  test(`reactive downstream sets (${label})`, () => {
    const { downstream } = graphFromDag(sc.doc)
    assert.deepEqual(sorted(collectDownstream(['mutator'], downstream)), READERS)
    assert.deepEqual(sorted(collectDownstream(['builder'], downstream)), ['mutator', ...READERS])
    assert.deepEqual(sorted(collectDownstream(['holiday'], downstream)), ['mutator', ...READERS])
    assert.deepEqual(sorted(collectDownstream(['demand'], downstream)), ['builder', 'mutator', ...READERS])
    assert.deepEqual(sorted(collectDownstream(['kbparams'], downstream)), ['kb'])
    assert.deepEqual(sorted(collectDownstream(['r42'], downstream)), [])
    assert.deepEqual(sorted(collectDownstream(['unrelated'], downstream)), [])
  })

  test(`upstream walk and lineage of PY-17 reach the builder and its sources (${label})`, () => {
    const { upstream } = graphFromDag(sc.doc)
    assert.deepEqual(sorted(collectUpstream(['r42'], upstream)), ['builder', 'demand', 'holiday', 'mutator', 'reco'])
    const cells = liveCells(sc)
    const lin = buildLineage('r42', cells, sc.doc, [])
    assert.deepEqual(lin.steps.map(s => s.cellId), ['demand', 'reco', 'holiday', 'builder', 'mutator', 'r42'])
    const by = Object.fromEntries(lin.sources.map(s => [s.id, s]))
    assert.deepEqual(by['microvm_demo_db.orders'].steps.map(s => s.cellId), ['demand'])
    assert.deepEqual(by['ecommerce-recommendations'].steps.map(s => s.cellId), ['reco'])
    assert.deepEqual(by['https://date.nager.at'].steps.map(s => s.cellId), ['holiday'])
    assert.equal(by['https://date.nager.at'].readByThisCell, false)
    assert.equal(by.AVSDQZX2CR.readByThisCell, true)
    assert.ok(lin.trust.reasons.some(r => r.startsWith('https://date.nager.at is fetched from a URL') && r.endsWith('— via PY-2')),
      lin.trust.reasons.join(' | '))
    const mut = lin.steps.find(s => s.cellId === 'mutator')
    assert.deepEqual(sorted(mut.varsIn), ['products360', 'season_multiplier'])
  })
}

test('changing a PY-10 slider marks the products360 readers stale (not upstream / unrelated cells)', () => {
  const sc = CHAIN.after_mutator
  const stale = staleNodes(sc.doc)
  assert.deepEqual(sorted(stale.keys()), READERS)
  assert.deepEqual(stale.get('r42').via, ['mutator'])
  assert.deepEqual(sorted(changedVarsSince(sc.doc.runtime.vars, sc.baseline_clock)), ['products360', 'stockout_risk_days'])
})

test('re-running the builder marks the mutator and then the readers stale', () => {
  const sc = CHAIN.after_builder
  assert.deepEqual(sorted(staleNodes(sc.doc).keys()), ['mutator', ...READERS])
  const g = graphFromDag(sc.doc)
  for (const r of READERS) assert.equal(g.inputsOf.get(r).get('products360'), 'mutator', 'readers still read the mutated version')
  assert.equal(sc.doc.runtime.vars.products360.last_cell, 'builder', 'runtime last_cell (stored) owns the variable')
})

test('changing the holiday multiplier stales PY-10 and its downstream', () => {
  const sc = CHAIN.after_holiday
  assert.deepEqual(sorted(staleNodes(sc.doc).keys()), ['mutator', ...READERS])
  assert.deepEqual([...changedVarsSince(sc.doc.runtime.vars, sc.baseline_clock)], ['season_multiplier'])
})

test('reactive toRun = downstream(ran) ∩ staleNodes, ordered by position', () => {
  const sc = CHAIN.after_mutator
  const g = graphFromDag(sc.doc)
  const stale = staleNodes(sc.doc)
  const down = collectDownstream(['mutator'], g.downstream)
  const toRun = orderByPosition([...down].filter(id => stale.has(id)), liveCells(sc))
  assert.deepEqual(toRun, READERS)
})

test('two mutators chain in order; readers between them read the earlier version', () => {
  const sc = scenarios('dag_two_mutators.json').ran
  const g = graphFromDag(sc.doc)
  assert.equal(g.inputsOf.get('m1').get('df'), 'b')
  assert.equal(g.inputsOf.get('mid').get('df'), 'm1')
  assert.equal(g.inputsOf.get('m2').get('df'), 'm1')
  assert.equal(g.inputsOf.get('end').get('df'), 'm2')
  assert.deepEqual(sorted(collectDownstream(['m1'], g.downstream)), ['end', 'm2', 'mid'])
  assert.deepEqual(sorted(collectDownstream(['m2'], g.downstream)), ['end'])
  assert.equal(findCycleCells(g.downstream).size, 0)
})

test('plain def-use and out-of-order reads keep the previous behaviour', () => {
  const sc = scenarios('dag_out_of_order.json')
  assert.deepEqual(sc.ran.doc.edges.map(e => [e.from, e.to, e.var, e.backward]), [['w', 'r', 'x', true]])
  // A cell that both reads and writes x with no earlier producer gets no self-edge.
  assert.deepEqual(sc.self_read.doc.edges, [])
  assert.equal(graphFromDag(sc.self_read.doc).upstream.size, 0)
})

test('dependency cycle cells are found for the reactive guard', () => {
  const sc = scenarios('dag_cycle.json').ran
  assert.deepEqual(sorted(findCycleCells(graphFromDag(sc.doc).downstream)), ['a', 'b'])
})

test('graphFromDag tolerates a missing or foreign document', () => {
  for (const doc of [null, undefined, {}, { schema: 2, nodes: [] }]) {
    const g = graphFromDag(doc)
    assert.equal(g.edges.length, 0)
    assert.equal(g.nodeById.size, 0)
    assert.equal(staleNodes(doc).size, 0)
  }
})

test('staleNodes includes edited nodes that carry a stale_reason (and transitive stale)', () => {
  const st = scenarios('dag_status.json')
  assert.equal(staleNodes(st.edited_unsaved.doc).size, 0)
  const stale = staleNodes(st.edited_with_reason.doc)
  assert.deepEqual(sorted(stale.keys()), ['c2', 'c3'])
  const c2 = graphFromDag(st.edited_with_reason.doc).nodeById.get('c2')
  assert.equal(c2.status, 'edited')
  assert.deepEqual(stale.get('c2'), { kind: 'upstream_changed', vars: ['x'], via: ['c1'] })
  assert.deepEqual(stale.get('c3'), { kind: 'upstream_stale', vars: [], via: ['c2'] })
  const cold = staleNodes(st.not_in_checkpoint.doc)
  assert.equal(cold.get('c1').kind, 'not_in_checkpoint')
})

test('changedVarsSince / maxClock over runtime vars', () => {
  const vars = CHAIN.with_provenance.doc.runtime.vars
  assert.equal(maxClock(vars), 6)
  assert.equal(maxClock({}), 0)
  assert.equal(maxClock(undefined), 0)
  assert.deepEqual(sorted(changedVarsSince(vars, 4)), ['kb_query', 'kb_top_k', 'products360', 'stockout_risk_days'])
  assert.equal(changedVarsSince(vars, 6).size, 0)
  assert.equal(changedVarsSince(vars, 0).size, Object.keys(vars).length)
  assert.equal(changedVarsSince(null, 0).size, 0)
})

test('run baseline is per VM: a runtime from another VM compares against clock 0', () => {
  const old = { schema: 1, nodes: [], runtime: { vm_id: 'vm-old', clock: 40, vars: {} } }
  const base = runBaseline(old)
  assert.deepEqual(base, { clock: 40, vmId: 'vm-old' })
  assert.deepEqual(runBaseline(null), { clock: 0, vmId: null })
  const fresh = { vm_id: 'vm-new', clock: 2, vars: { a: { last_exec: 1 }, b: { last_exec: 2 } } }
  assert.deepEqual(sorted(changedVarsSinceBaseline(fresh, base)), ['a', 'b'], 'VM switch resets the baseline')
  const same = { vm_id: 'vm-old', clock: 42, vars: { a: { last_exec: 40 }, b: { last_exec: 41 } } }
  assert.deepEqual([...changedVarsSinceBaseline(same, base)], ['b'], 'same VM keeps the clock baseline')
  assert.deepEqual(sorted(changedVarsSinceBaseline(fresh, runBaseline(null))), ['a', 'b'])
  assert.equal(changedVarsSinceBaseline(null, base).size, 0)
})

test('newerDag orders (version, runtime_version) pairs; built_at only breaks a tie', () => {
  const a = CHAIN.with_provenance.doc
  // no_provenance differs from with_provenance only in the runtime section: the
  // stamper keeps version/built_at and raises runtime_version (runtime-only write).
  const b = CHAIN.no_provenance.doc
  assert.equal(b.version, a.version)
  assert.equal(b.built_at, a.built_at)
  assert.ok(b.runtime_version > a.runtime_version)
  assert.equal(newerDag(null, a), true)
  assert.equal(newerDag(a, b), true, 'same version, higher runtime_version is newer')
  assert.equal(newerDag(b, a), false)
  assert.equal(newerDag(a, a), false)
  assert.equal(newerDag(a, null), false)
  assert.equal(newerDag(a, { ...a, version: a.version + 1, runtime_version: 0 }), true, 'version dominates')
  assert.equal(newerDag(b, { ...b, version: b.version - 1, runtime_version: 99 }), false)
  assert.equal(newerDag(a, { ...a, schema: 2, version: 99 }), false, 'foreign schema is treated as absent')
  assert.equal(newerDag(a, { ...a, built_at: '2099-01-01T00:00:00.000Z' }), true, 'equal pair: later built_at')
  assert.equal(newerDag(b, { ...a, built_at: '2099-01-01T00:00:00.000Z' }), false, 'lower pair: built_at ignored')
  const legacy = { ...a }
  delete legacy.runtime_version
  assert.equal(newerDag(legacy, a), true, 'absent runtime_version reads as 0')
})

test('withDagProvenance overlays runtime provenance and ignores the VM fields', () => {
  const doc = CHAIN.with_provenance.doc
  const variables = {
    products360: { type: 'DataFrame', defined_by: 'stale-vm-id', last_cell: 'x', last_exec: 99 },
    not_in_dag: { type: 'int', defined_by: 'vm-cell', modified_by: ['y'] },
  }
  const out = withDagProvenance(variables, doc)
  assert.deepEqual(out.products360, {
    type: 'DataFrame', defined_by: 'builder', defined_at: 4, modified_by: ['mutator'], last_cell: 'mutator', last_exec: 5,
  })
  assert.deepEqual(out.not_in_dag, {
    type: 'int', defined_by: null, defined_at: null, modified_by: [], last_cell: null, last_exec: null,
  })
  assert.equal(variables.products360.defined_by, 'stale-vm-id', 'input not mutated')
  assert.equal(withDagProvenance(variables, null), variables, 'no document → unchanged')
})

test('effectiveStatus: the live cell is the only edited signal (finding 5)', () => {
  const st = scenarios('dag_status.json')
  const node = (sc, id) => graphFromDag(sc.doc).nodeById.get(id)
  // Node edited (autosave not landed) but live code === lastExecutedCode → current.
  const [, c2] = liveCells(st.edited_unsaved)
  assert.equal(node(st.edited_unsaved, 'c2').status, 'edited')
  assert.equal(effectiveStatus(c2, node(st.edited_unsaved, 'c2')), 'current')
  // + a stale_reason → stale.
  assert.equal(effectiveStatus(c2, node(st.edited_with_reason, 'c2')), 'stale')
  // Live code !== lastExecutedCode → edited whatever the node says.
  const typed = { ...c2, code: c2.code + ' # edit' }
  assert.equal(effectiveStatus(typed, node(st.edited_unsaved, 'c1')), 'edited')
  assert.equal(effectiveStatus(typed, node(st.edited_with_reason, 'c2')), 'edited')
  // Without a live cell the node's edited status is honoured.
  assert.equal(effectiveStatus(null, node(st.edited_unsaved, 'c2')), 'edited')
  // Errors win; never_run and not_in_checkpoint read as stale.
  assert.equal(effectiveStatus({ ...c2, error: 'boom' }, node(st.edited_unsaved, 'c2')), 'error')
  assert.equal(effectiveStatus(c2, { status: 'error' }), 'error')
  assert.equal(effectiveStatus({ id: 'n', code: 'x' }, { status: 'never_run', stale_reason: null }), 'stale')
  assert.equal(effectiveStatus(liveCells(st.not_in_checkpoint)[0], node(st.not_in_checkpoint, 'c1')), 'stale')
  assert.equal(effectiveStatus(liveCells(st.edited_unsaved)[0], node(st.edited_unsaved, 'c1')), 'current')
})

test('SQL output-variable derivation matches the Python port (shared fixture)', () => {
  const cases = load('sql_output_variable_cases.json')
  assert.ok(cases.length >= 10)
  for (const { sql, expected } of cases) assert.equal(deriveSqlOutputVariable(sql), expected, JSON.stringify(sql))
})

// --- relatedCells: one transitive closure with depth (drawer + Outline) -----------
const syntheticDoc = (ids, edges) => ({
  schema: 1,
  nodes: ids.map((id, i) => ({ cell_id: id, position: i })),
  edges: edges.map(([from, to]) => ({ from, to, var: `${from}_${to}` })),
})

test('relatedCells: direct edges are depth 1, indirect deeper, seed excluded', () => {
  // a → b → c → d and a → d
  const g = graphFromDag(syntheticDoc(['a', 'b', 'c', 'd'], [['a', 'b'], ['b', 'c'], ['c', 'd'], ['a', 'd']]))
  const up = relatedCells(g, 'd')
  assert.deepEqual(Object.fromEntries(up.upstream), { c: 1, a: 1, b: 2 })
  assert.deepEqual(Object.fromEntries(up.downstream), {})
  const down = relatedCells(g, 'a')
  assert.deepEqual(Object.fromEntries(down.downstream), { b: 1, d: 1, c: 2 })
  assert.deepEqual(Object.fromEntries(down.upstream), {})
  assert.equal(up.upstream.has('d'), false, 'seed is never its own related cell')
})

test('relatedCells: cycle-safe, each cell at its shortest depth', () => {
  // a → b → c → d → a (cycle through the seed)
  const g = graphFromDag(syntheticDoc(['a', 'b', 'c', 'd'], [['a', 'b'], ['b', 'c'], ['c', 'd'], ['d', 'a']]))
  const r = relatedCells(g, 'a')
  assert.deepEqual(Object.fromEntries(r.upstream), { d: 1, c: 2, b: 3 })
  assert.deepEqual(Object.fromEntries(r.downstream), { b: 1, c: 2, d: 3 })
  assert.equal(r.upstream.has('a'), false)
  assert.equal(r.downstream.has('a'), false)
})

test('relatedCells: no document or unknown cell gives empty sets', () => {
  const empty = relatedCells(graphFromDag(null), 'x')
  assert.equal(empty.upstream.size, 0)
  assert.equal(empty.downstream.size, 0)
  const g = graphFromDag(syntheticDoc(['a'], []))
  assert.equal(relatedCells(g, 'missing').upstream.size, 0)
})

// Parity: buildLineage (drawer steps and Used by) and relatedCells (Outline) agree on
// every cell of every stored scenario, markdown excluded from the drawer lists.
const PARITY = [
  ...Object.entries(scenarios('dag_lineage.json')).map(([k, v]) => [`dag_lineage/${k}`, v]),
  ...Object.entries(scenarios('dag_cycle.json')).map(([k, v]) => [`dag_cycle/${k}`, v]),
  ...Object.entries(CHAIN).map(([k, v]) => [`dag_mutation_chain/${k}`, v]),
]
for (const [name, sc] of PARITY) {
  test(`relatedCells matches buildLineage steps and Used by (${name})`, () => {
    const cells = liveCells(sc)
    const byId = new Map(cells.map(c => [String(c.id), c]))
    const nonMarkdown = (ids) => orderByPosition(ids, cells).filter(id => byId.get(id).type !== 'markdown')
    const graph = graphFromDag(sc.doc)
    for (const cell of cells) {
      const id = String(cell.id)
      const rel = relatedCells(graph, id)
      const lin = buildLineage(id, cells, sc.doc, [])
      assert.deepEqual(lin.steps.map(s => s.cellId), nonMarkdown([id, ...rel.upstream.keys()]), `steps of ${id}`)
      assert.deepEqual(lin.usedBy.map(s => s.cellId), nonMarkdown(rel.downstream.keys()), `Used by of ${id}`)
      const directUp = [...rel.upstream].filter(([, d]) => d === 1).map(([k]) => k)
      assert.deepEqual(sorted(directUp), sorted(graph.upstream.get(id) || []), `direct inputs of ${id}`)
    }
  })
}
